const DEFAULT_SETTINGS = { workspaceId: 't4h-default', actorId: 'browser-user', telemetryMode: 'local', queueEndpoint: '', overlayEnabled: true };

chrome.runtime.onInstalled.addListener(async () => {
  const existing = await chrome.storage.sync.get('signalSettings');
  if (!existing.signalSettings) await chrome.storage.sync.set({ signalSettings: DEFAULT_SETTINGS });
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === 'SIGNAL_CAPTURE') {
    handleSignalCapture(message.payload, sender).then(sendResponse).catch((error) => sendResponse({ ok: false, error: String(error) }));
    return true;
  }
});

async function handleSignalCapture(payload, sender) {
  const { signalSettings } = await chrome.storage.sync.get('signalSettings');
  const settings = { ...DEFAULT_SETTINGS, ...(signalSettings || {}) };
  const event = buildTelemetryEvent(payload, sender, settings);
  const queueJob = buildQueueJob(event, settings);
  await chrome.storage.local.set({ [`event:${event.event_id}`]: event, [`job:${queueJob.idempotency_key}`]: queueJob });
  if (settings.queueEndpoint) {
    await fetch(settings.queueEndpoint, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(queueJob) });
  }
  return { ok: true, event, queueJob };
}

function buildTelemetryEvent(payload, sender, settings) {
  const now = new Date().toISOString();
  const event_id = `sig_${Date.now()}_${Math.random().toString(16).slice(2)}`;
  return {
    event_id,
    event_type: 'browser.signal.capture',
    workspace_id: settings.workspaceId,
    actor_id: settings.actorId,
    occurred_at: now,
    source: 'signal-browser-runtime',
    page: { title: payload.title, url: payload.url, host: payload.host },
    signal: { text: payload.selection || payload.note || '', mode: payload.mode || 'capture', confidence: 0.7 },
    evidence_state: 'PARTIAL',
    sender_tab_id: sender?.tab?.id || null
  };
}

function buildQueueJob(event, settings) {
  return {
    idempotency_key: `signal_browser_${event.event_id}`,
    title: `Process browser signal: ${event.page.host || 'unknown'}`,
    origin: 'signal-browser-runtime',
    destination: 'runtime.worker',
    env: 'dev',
    status: 'queued',
    payload: { event },
    evidence_state: 'PARTIAL',
    close_signal: false
  };
}

function ensureSignalButton() {
  if (document.getElementById('signal-runtime-button')) return;
  const btn = document.createElement('button');
  btn.id = 'signal-runtime-button';
  btn.textContent = 'Signal';
  btn.title = 'Capture this page as a Signal';
  btn.onclick = async () => {
    const selection = window.getSelection()?.toString() || '';
    const payload = { title: document.title, url: location.href, host: location.host, selection, mode: selection ? 'selection' : 'page' };
    const result = await chrome.runtime.sendMessage({ type: 'SIGNAL_CAPTURE', payload });
    btn.textContent = result?.ok ? 'Captured' : 'Failed';
    setTimeout(() => (btn.textContent = 'Signal'), 1500);
  };
  document.body.appendChild(btn);
}
ensureSignalButton();

document.getElementById('capture').onclick = async () => {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  const payload = { title: tab.title, url: tab.url, host: new URL(tab.url).host, mode: 'popup' };
  const result = await chrome.runtime.sendMessage({ type: 'SIGNAL_CAPTURE', payload });
  document.getElementById('out').textContent = JSON.stringify(result, null, 2);
};

document.getElementById('capture').onclick = async () => {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  const note = document.getElementById('note').value;
  const payload = { title: tab.title, url: tab.url, host: new URL(tab.url).host, note, mode: 'sidepanel' };
  const result = await chrome.runtime.sendMessage({ type: 'SIGNAL_CAPTURE', payload });
  document.getElementById('out').textContent = JSON.stringify(result, null, 2);
};

const event = { event_id: 'sig_test_' + Date.now(), page: { title: 'Smoke Test', url: 'https://example.com', host: 'example.com' }, signal: { text: 'test', mode: 'smoke' } };
const job = { idempotency_key: 'signal_browser_' + event.event_id, title: 'Process browser signal smoke test', origin: 'signal-browser-runtime', destination: 'runtime.worker', status: 'queued', payload: { event }, evidence_state: 'PARTIAL' };
console.log(JSON.stringify({ ok: true, event, job }, null, 2));
